#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Production env goes next to the compose file on the VPS, so it must not be
# mixed into the local .env.local the app already uses.
ENV_FILE=".env.production"

# Values that should be generated, never typed. node is guaranteed here because
# the project itself runs on it.
gen_b64() { node -e "process.stdout.write(require('node:crypto').randomBytes(32).toString('base64'))"; }
gen_hex() { node -e "process.stdout.write(require('node:crypto').randomBytes($1).toString('hex'))"; }

run_wizard() {

TOTAL_STAGES=9

banner "Setup VPS untuk PaaS"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "VPS: alamat dan user"
say "Ambil IP publik VPS dari panel provider-mu."
note "Provider-mu bukan yang umum, jadi wizard tidak membuka panelnya; cari menu"
note "Server / VPS lalu salin IP publik (IPv4)."
ask VPS_HOST "IP atau hostname VPS:"
ask VPS_PORT "Port SSH [22]:"
VPS_PORT="${VPS_PORT:-22}"
ask VPS_USER "User SSH [root]:"
VPS_USER="${VPS_USER:-root}"
if [[ -z "$VPS_HOST" ]]; then
  warn "IP VPS kosong, jadi stage berikutnya tidak bisa dijalankan."
  exit 1
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "SSH: pasang kunci"
say "Login password tidak nyaman untuk deploy berulang. Kita pasang SSH key."
if [[ ! -f "$HOME/.ssh/id_ed25519" ]]; then
  step "Buat kunci baru (tekan Enter 3x):"
  say "ssh-keygen -t ed25519 -C \"paas-vps\""
  pause "Tekan Enter setelah kunci dibuat..."
fi
if [[ ! -f "$HOME/.ssh/id_ed25519.pub" ]]; then
  warn "Public key tidak ditemukan di $HOME/.ssh/id_ed25519.pub"
  exit 1
fi
PUBKEY=$(cat "$HOME/.ssh/id_ed25519.pub")
say "Public key-mu:"
printf '  %s\n' "$PUBKEY"
step "Masuk ke VPS dengan password, lalu jalankan:"
say "ssh -p $VPS_PORT $VPS_USER@$VPS_HOST"
say "mkdir -p ~/.ssh && chmod 700 ~/.ssh"
say "echo '$PUBKEY' >> ~/.ssh/authorized_keys && chmod 600 ~/.ssh/authorized_keys"
step "Uji dari mesin ini (harus tanpa password):"
say "ssh -p $VPS_PORT $VPS_USER@$VPS_HOST 'echo ok'"
pause "Tekan Enter kalau login tanpa password sudah berhasil..."
note "Setelah key berhasil, matikan login password di /etc/ssh/sshd_config"
note "(PasswordAuthentication no), lalu sudo systemctl restart ssh."
note "Password yang pernah dibagikan lewat chat harus dianggap bocor."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Docker di VPS"
step "Masuk ke VPS:"
say "ssh -p $VPS_PORT $VPS_USER@$VPS_HOST"
step "Install Docker resmi:"
say "curl -fsSL https://get.docker.com | sh"
step "Kalau user bukan root, izinkan docker tanpa sudo:"
say "sudo usermod -aG docker $VPS_USER && newgrp docker"
step "Verifikasi:"
say "docker --version && docker compose version"
pause "Tekan Enter setelah 'Docker Compose version' muncul..."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "DNS: A record"
say "Buka panel DNS domain-mu, cari menu DNS / Records."
ask DASHBOARD_DOMAIN "Domain dashboard (mis. console.example.com):"
ask PLATFORM_DOMAIN "Domain Service (mis. apps.example.com):"
if [[ -z "$DASHBOARD_DOMAIN" || -z "$PLATFORM_DOMAIN" ]]; then
  warn "Kedua domain harus diisi: satu untuk dashboard, satu untuk Service."
  exit 1
fi
step "Tambahkan dua A record ke $VPS_HOST (TTL 300):"
say "  $DASHBOARD_DOMAIN        → $VPS_HOST"
say "  *.$PLATFORM_DOMAIN       → $VPS_HOST"
note "Wildcard wajib: tiap Service mendapat subdomain sendiri."
step "Verifikasi propagasi (bisa sampai beberapa menit):"
say "nslookup $DASHBOARD_DOMAIN"
say "nslookup test.$PLATFORM_DOMAIN"
pause "Tekan Enter setelah kedua nama mengarah ke $VPS_HOST..."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Secret produksi"
say "Nilai ini dibuat otomatis, bukan diketik. Jangan bagikan .env.production."
BETTER_AUTH_SECRET=$(gen_b64)
ENV_ENCRYPTION_KEY=$(gen_b64)
AGENT_TOKEN=$(gen_hex 32)
POSTGRES_PASSWORD=$(gen_hex 16)
write_env BETTER_AUTH_SECRET "$BETTER_AUTH_SECRET"
write_env ENV_ENCRYPTION_KEY "$ENV_ENCRYPTION_KEY"
write_env AGENT_TOKEN "$AGENT_TOKEN"
write_env POSTGRES_PASSWORD "$POSTGRES_PASSWORD"
write_env DATABASE_URL "postgresql://stealth:$POSTGRES_PASSWORD@postgres:5432/stealth_hosting"
write_env BETTER_AUTH_URL "https://$DASHBOARD_DOMAIN"
write_env NEXT_PUBLIC_BETTER_AUTH_URL "https://$DASHBOARD_DOMAIN"
write_env DASHBOARD_DOMAIN "$DASHBOARD_DOMAIN"
write_env PLATFORM_DOMAIN "$PLATFORM_DOMAIN"
write_env PLATFORM_IP "$VPS_HOST"
write_env AGENT_BASE_URL "http://agent:8081"
write_env AGENT_NAME "node-1"
write_env CADDY_ADMIN_URL "http://caddy:2019"
write_env CADDY_CONTAINER_NAME "stealth-caddy"
write_env CONTROL_PLANE_URL "http://control-plane:3000"
write_env NODE_ENV "production"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Resend (opsional)"
if confirm "Pakai Resend untuk email undangan Organization?"; then
  open_url "https://resend.com/api-keys"
  step "Create API Key, lalu copy nilai yang berawalan re_."
  ask_secret RESEND_API_KEY "Paste RESEND_API_KEY:"
  write_env RESEND_API_KEY "$RESEND_API_KEY"
else
  note "Dilewati. Email undangan tidak akan terkirim sampai RESEND_API_KEY diisi."
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare Tunnel"
say "VPS ini tidak membuka port 80/443. Semua traffic masuk lewat tunnel."
open_url "https://one.dash.cloudflare.com"
step "Zero Trust → Networks → Tunnels → Create a tunnel → Cloudflared."
step "Beri nama (mis. paas), lalu copy token dari halaman install."
step "Tambahkan dua Public Hostname:"
say "  $DASHBOARD_DOMAIN  →  http://control-plane:3000"
say "  *.$PLATFORM_DOMAIN →  https://caddy:443   (aktifkan No TLS Verify)"
note "Cloudflare membuat CNAME-nya otomatis; tidak perlu A record ke IP VPS."
ask_secret CLOUDFLARE_TUNNEL_TOKEN "Paste tunnel token:"
write_env CLOUDFLARE_TUNNEL_TOKEN "$CLOUDFLARE_TUNNEL_TOKEN"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "S3 backup (opsional)"
if confirm "Pakai S3-compatible (RustFS/MinIO) untuk Backup?"; then
  ask S3_ENDPOINT "Endpoint S3 (mis. http://rustfs:9000):"
  ask S3_BUCKET "Bucket:"
  ask S3_REGION "Region [us-east-1]:"
  S3_REGION="${S3_REGION:-us-east-1}"
  ask S3_ACCESS_KEY_ID "Access key id:"
  ask_secret S3_SECRET_ACCESS_KEY "Secret access key:"
  write_env S3_ENDPOINT "$S3_ENDPOINT"
  write_env S3_BUCKET "$S3_BUCKET"
  write_env S3_REGION "$S3_REGION"
  write_env S3_ACCESS_KEY_ID "$S3_ACCESS_KEY_ID"
  write_env S3_SECRET_ACCESS_KEY "$S3_SECRET_ACCESS_KEY"
else
  note "Dilewati. Backup jatuh ke disk lokal (fallback yang sudah ada di kode)."
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Kirim env ke VPS"
ask DEPLOY_DIR "Direktori deploy di VPS [/home/ubuntu/paas]:"
DEPLOY_DIR="${DEPLOY_DIR:-/home/ubuntu/paas}"
step "Di VPS, buat direktori:"
say "mkdir -p $DEPLOY_DIR"
step "Dari mesin ini, kirim file env:"
say "scp -P $VPS_PORT .env.production $VPS_USER@$VPS_HOST:$DEPLOY_DIR/.env"
step "Jalankan stack (dari direktori repo yang sudah disalin):"
say "cd $DEPLOY_DIR && docker compose -f docker-compose.production.yml up -d --build"
note "Detail lengkap ada di docs/deployment/vps.md."

finish
}

run_wizard "$@"; exit
